            //
            aScatter = (RotL64(aPrevious, 3U) ^ RotL64(aCross, 53U)) + (RotL64(aIngress, 22U) ^ RotL64(aCarry, 41U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterF = ((aWandererD + RotL64(aPrevious, 57U)) + 0xB26FB4753C5A4990ULL) + aOASaltC[(((511U - aIndex) + 237U)) & S_SALT1];
            aOrbiterD = (aWandererH + RotL64(aIngress, 51U)) + 0x2DA8376CB5636E0FULL;
            aOrbiterC = (((aWandererF + RotL64(aScatter, 34U)) + RotL64(aCarry, 41U)) + 0x4C2B72F5EF60A264ULL) + aOASaltB[(((511U - aIndex) + 141U)) & S_SALT1];
            aOrbiterH = (((aWandererG + RotL64(aCross, 23U)) + RotL64(aCarry, 53U)) + 0x28B3D2347514B2C1ULL) + aOASaltG[((aIndex + 133U)) & S_SALT1];
            aOrbiterG = (aWandererJ + RotL64(aIngress, 13U)) + 0xD1C669CB3E7B50DEULL;
            aOrbiterA = (((aWandererA + RotL64(aPrevious, 5U)) + RotL64(aCarry, 29U)) + 0x5D63148F0F993423ULL) + aOASaltH[(((511U - aIndex) + 408U)) & S_SALT1];
            aOrbiterE = (aWandererK + RotL64(aScatter, 41U)) + 0x787B07694E1AA99CULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x5DBF8C5A4B442E9DULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0xAFC18323F3B48A17ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xD5519B88311768ADULL), 39U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x6A98C07757365A85ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterH) ^ 0xAE5DF1452A9CA12DULL) ^ aOUSaltD[((aIndex + 393U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0xC92614395E5BBBDDULL), 11U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterH) + 0xC1BBB778A6C30AAEULL) + aOUSaltF[((aIndex + 278U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xD2994438A4645588ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x93E0FB9FDB168A3DULL), 3U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0xC365F1D9D357B3DDULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterE) ^ 0xA5A4A0DE68DAF9E4ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x7F5F4486ADD91BF9ULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0xD2D730A638E31E5DULL) + aOUSaltA[(((511U - aIndex) + 509U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x758A52BEFBC7453FULL;
            aOrbiterD = RotL64((aOrbiterD * 0xBB174D3D47124839ULL), 47U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x57B2C2AE44295BCFULL) + aOUSaltG[((aIndex + 110U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterG) ^ 0x55519E107704BD2AULL) ^ aOUSaltH[(((511U - aIndex) + 501U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x0EBDC5BE5F8FCE6DULL), 19U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0xFB9F17ABE97718B2ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x140B88F12BFBB95EULL;
            aOrbiterH = RotL64((aOrbiterH * 0x8C95D2720D6459D5ULL), 53U);
            //
            aIngress = aOrbiterE ^ RotL64(aOrbiterF, 43U);
