            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterC, 35U));
            aIngress = aIngress + RotL64(aOrbiterH, 19U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererH = aWandererH ^ ((RotL64(aIngress, 41U) + RotL64(aOrbiterC, 13U)) + aOrbiterE);
            aWandererJ = aWandererJ + ((((RotL64(aPrevious, 11U) + RotL64(aOrbiterC, 23U)) + aOrbiterA) + RotL64(aCarry, 47U)) + aWUSaltC[((aIndex + 463U)) & S_SALT1]);
            aWandererF = aWandererF ^ (((RotL64(aScatter, 29U) + aOrbiterG) + RotL64(aOrbiterE, 29U)) + aWUSaltH[((aIndex + 424U)) & S_SALT1]);
            aWandererD = aWandererD + ((((RotL64(aCross, 35U) + RotL64(aOrbiterH, 57U)) + aOrbiterC) + RotL64(aCarry, 3U)) + aWUSaltB[(((511U - aIndex) + 30U)) & S_SALT1]);
            aWandererA = aWandererA ^ (((RotL64(aScatter, 21U) + aOrbiterD) + RotL64(aOrbiterH, 43U)) + aWUSaltD[((aIndex + 49U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aIngress, 4U) + RotL64(aOrbiterF, 50U)) + aOrbiterD);
            aWandererG = aWandererG ^ (((RotL64(aCross, 47U) + RotL64(aOrbiterH, 3U)) + aOrbiterF) + aWUSaltE[(((511U - aIndex) + 504U)) & S_SALT1]);
            //
