            aCarry = aCarry + (RotL64(aWandererA, 18U) ^ aWandererD);
            aCarry = aCarry + RotL64(aWandererG, 23U);
            aCarry = aCarry + RotL64(aIngress, 13U);
            aCarry = TwistMix64::DiffuseB(aCarry);
            //
