            aOrbiterE = RotL64((aOrbiterE * 0xE2BA5CE4D6E4D533ULL), 3U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x7B4BF4DD582F2C55ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterH) ^ 0x1D74A3FAF54453E9ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x43106706472A95BBULL), 23U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0xF552C88E84340D4DULL;
