            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x3E7E67642F06BC89ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xDDFD0D2141512AA8ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x824363DCB454DEB3ULL), 41U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0xCD072678B73E6F65ULL) + aOUSaltD[(((511U - aIndex) + 395U)) & S_SALT1];
